import{_ as s,B as n,o,c as d,j as t,a as r,b as h,w as a,E as l,ah as c,ax as p}from"./chunks/framework.Bnt0oLax.js";const v=JSON.parse('{"title":"Extensions","description":"Extensions — widgets, scripts, and stylesheets declared in a single registry file and published from your Git repository","frontmatter":{"description":"Extensions — widgets, scripts, and stylesheets declared in a single registry file and published from your Git repository"},"headers":[],"relativePath":"custom-widgets/v2/index.md","filePath":"custom-widgets/v2/index.md"}'),u={name:"custom-widgets/v2/index.md"};function m(y,e,f,g,b,x){const i=n("Mermaid");return o(),d("div",null,[e[1]||(e[1]=t("div",{style:{display:"none"},hidden:"","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2.md for this page in Markdown format",-1)),e[2]||(e[2]=t("h1",{id:"extensions",tabindex:"-1"},[r("Extensions "),t("a",{class:"header-anchor",href:"#extensions","aria-label":'Permalink to "Extensions"'},"​")],-1)),e[3]||(e[3]=t("p",null,[r("Extensions let you customize your community from code. You declare "),t("strong",null,"widgets"),r(", "),t("strong",null,"scripts"),r(", and "),t("strong",null,"stylesheets"),r(" in a single registry file in your Git repository, push to your watched branch, and the platform publishes everything automatically.")],-1)),(o(),h(c,null,{default:a(()=>[l(i,{id:"mermaid-7",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20repo%5B%22Your%20Code%20Repository%22%5D%20--%3E%20push%5B%22Push%20to%20branch%22%5D%20--%3E%20platform%5B%22Extensions%20published%22%5D%0A%0A%20%20%20%20style%20repo%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20push%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20platform%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=p('<h2 id="the-three-extension-types" tabindex="-1">The Three Extension Types <a class="header-anchor" href="#the-three-extension-types" aria-label="Permalink to &quot;The Three Extension Types&quot;">​</a></h2><p>You can publish any combination of the three types — one, two, or all three. They share the same registry file, the same publishing pipeline, and the same page-targeting rules.</p><table tabindex="0"><thead><tr><th>Type</th><th>What it is</th><th>Scope</th><th>When to use</th></tr></thead><tbody><tr><td><a href="./build-first-widget.html"><strong>Widgets</strong></a></td><td>Interactive components placed on pages via the No-Code Builder</td><td>One placed instance per page zone</td><td>Build tailored UI — forms, dashboards, dynamic content</td></tr><tr><td><a href="./scripts-overview.html"><strong>Scripts</strong></a></td><td>Global JavaScript injected into the page</td><td>Every matching page</td><td>Analytics, tracking, shared utilities</td></tr><tr><td><a href="./stylesheets-overview.html"><strong>Stylesheets</strong></a></td><td>Global CSS injected into the page</td><td>Every matching page</td><td>Sitewide theming, fonts, design tokens</td></tr></tbody></table><h2 id="the-registry-file" tabindex="-1">The Registry File <a class="header-anchor" href="#the-registry-file" aria-label="Permalink to &quot;The Registry File&quot;">​</a></h2><p>Every extension you publish is declared in a single file at the root of your repository: <code>extensions_registry.json</code>. See <a href="./registry-reference.html">Registry Reference</a> for the root object specification and <a href="./project-setup.html">Repository Layout</a> for how to structure your repository around it.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Connect</strong> — Link your GitHub organization to the platform.</li><li><strong>Configure</strong> — Select which repositories and branches to watch.</li><li><strong>Push</strong> — Commit changes to your watched branch.</li><li><strong>Publish</strong> — Extensions update within seconds.</li></ol><p>For publishing details, see <a href="./build-and-publish.html">Build &amp; Publish</a> and <a href="./repository-settings.html">Repository &amp; Branch Settings</a>.</p><h2 id="why-extensions" tabindex="-1">Why Extensions <a class="header-anchor" href="#why-extensions" aria-label="Permalink to &quot;Why Extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>For Developers</th><th>For Teams</th></tr></thead><tbody><tr><td>Version control for every change</td><td>No manual uploads</td></tr><tr><td>Pull requests and code review</td><td>Instant deployments</td></tr><tr><td>Branch-based environments</td><td>Audit trail via commits</td></tr><tr><td>Familiar Git workflow</td><td>Rollback via Git</td></tr></tbody></table><h2 id="branch-based-environments" tabindex="-1">Branch-Based Environments <a class="header-anchor" href="#branch-based-environments" aria-label="Permalink to &quot;Branch-Based Environments&quot;">​</a></h2><p>Each repository watches one branch at a time per community. Use separate communities to run multiple environments (dev, staging, production) — each watching its own branch.</p><p>See <a href="./repository-settings.html">Repository &amp; Branch Settings</a> and <a href="./../recipes/preview-and-promote.html">Preview and Promote</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>See <a href="./connect-github.html">Connect Your GitHub Account</a> for the GitHub and platform access you need, and <a href="./project-setup.html">Repository Layout</a> for the required <code>extensions_registry.json</code> file.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>See <a href="./repository-settings.html">Repository &amp; Branch Settings</a> for the one-watched-branch-per-community rule, and <a href="./project-setup.html">Repository Layout</a> for naming extensions uniquely.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Extension code is scanned for security issues before publishing, and every widget response includes security headers. See <a href="./content-security.html">Content Security</a> for details.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Pick the extension you want to build — each type has its own hands-on tutorial:</p><table tabindex="0"><thead><tr><th>You want to build...</th><th>Start with</th></tr></thead><tbody><tr><td>A custom interactive component</td><td><a href="./build-first-widget.html">Your First Widget</a></td></tr><tr><td>A global script</td><td><a href="./first-script.html">Your First Script</a></td></tr><tr><td>A global stylesheet</td><td><a href="./first-stylesheet.html">Your First Stylesheet</a></td></tr></tbody></table><p>New to the platform entirely? <a href="./connect-github.html">Connect Your GitHub Account</a> first, then return here.</p><p>Already familiar with the registry format? Go straight to the <a href="./registry-reference.html">Registry Reference</a> for the <code>extensions_registry.json</code> root object.</p>',24))])}const S=s(u,[["render",m]]);export{v as __pageData,S as default};
